      p.levelProgress = p.levelProgress || {1:1};
      if (!this.replayMode && !this.trainingMode) p.levelProgress[this.mapIndex + 1] = Math.max(p.levelProgress[this.mapIndex + 1] || 1, this.wave || 1);
      this.applyProfileRelics(save);
