      if(world===14){if(w<=2)return roll<.40?'solarFront':(roll<.64?'fighter':(roll<.88?'wreck':'capsule'));return roll<.30?'solarFront':(roll<.58?'fighter':(roll<.76?'wreck':(roll<.88?'capsule':'elite')));}
