        ctx.translate(it.x, it.y);
        ctx.scale(pulse, pulse);
        ctx.shadowBlur = it.major ? 28 : (it.rewardGlow ? 24 : ((it.type === 'power' || it.type === 'combo' || it.type==='critical') ? 16 : 9));
