            ctx.globalAlpha=.70;ctx.strokeStyle='#fff2b0';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(1,-4);ctx.lineTo(6,0);ctx.lineTo(1,4);ctx.moveTo(-3,-4);ctx.lineTo(-8,-8);ctx.moveTo(-3,4);ctx.lineTo(-8,8);ctx.stroke();
